import path from 'node:path';
import { migrate } from 'drizzle-orm/node-postgres/migrator';
import { readMigrationFiles } from 'drizzle-orm/migrator';
import type { Pool } from 'pg';
import type { Database } from './client';

/** Folder with the SQL migrations generated by drizzle-kit (works from src/ and dist/). */
export const MIGRATIONS_FOLDER = path.resolve(__dirname, '..', 'drizzle');

const ADVISORY_LOCK_KEY = 727_274_001;

/**
 * Databases created with `drizzle-kit push` have the tables but no migration journal. Mark the
 * bundled migrations as applied in that case so the migrator does not try to recreate them.
 */
async function baselineIfSchemaAlreadyPresent(pool: Pool): Promise<boolean> {
  await pool.query('CREATE SCHEMA IF NOT EXISTS "drizzle"');
  await pool.query(
    `CREATE TABLE IF NOT EXISTS "drizzle"."__drizzle_migrations" (
       id SERIAL PRIMARY KEY,
       hash text NOT NULL,
       created_at bigint
     )`,
  );

  const journal = await pool.query<{ count: string }>(
    'SELECT count(*)::text AS count FROM "drizzle"."__drizzle_migrations"',
  );
  if (Number(journal.rows[0]?.count ?? 0) > 0) return false;

  const existing = await pool.query<{ exists: boolean }>(
    `SELECT EXISTS (
       SELECT 1 FROM information_schema.tables
       WHERE table_schema = 'public' AND table_name = 'users'
     ) AS exists`,
  );
  if (!existing.rows[0]?.exists) return false;

  const migrations = readMigrationFiles({ migrationsFolder: MIGRATIONS_FOLDER });
  for (const migration of migrations) {
    await pool.query(
      'INSERT INTO "drizzle"."__drizzle_migrations" ("hash", "created_at") VALUES ($1, $2)',
      [migration.hash, migration.folderMillis],
    );
  }
  return true;
}

/** Applies pending SQL migrations. Safe to call concurrently from several instances. */
export async function runMigrations(db: Database, pool: Pool): Promise<void> {
  const lockClient = await pool.connect();
  try {
    await lockClient.query('SELECT pg_advisory_lock($1)', [ADVISORY_LOCK_KEY]);
    await baselineIfSchemaAlreadyPresent(pool);
    await migrate(db, { migrationsFolder: MIGRATIONS_FOLDER });
  } finally {
    try {
      await lockClient.query('SELECT pg_advisory_unlock($1)', [ADVISORY_LOCK_KEY]);
    } finally {
      lockClient.release();
    }
  }
}
